files.forEach(file => {
  let content = fs.readFileSync(file, 'utf8');
  let original = content;

  // Replace lines that only contain commas and whitespace
  content = content.replace(/^[\s,]+$/gm, '');

  // Replace multiple commas with a single comma
  content = content.replace(/,\s*,/g, ',');

  // Replace { , with {
  content = content.replace(/\{\s*,/g, '{');

  // Clean up any remaining leading commas inside module.exports = {
  content = content.replace(/module\.exports\s*=\s*\{\s*,+/g, 'module.exports = {');

  if (content !== original) {
    fs.writeFileSync(file, content, 'utf8');
    fixed++;
  }
});

