            ...(oid(query.campaignId) ? { campaignId: oid(query.campaignId) } : {}),
          },
        },
        {
          $group: {
            _id: null,
            pendingEscrowAmount: { $sum: "$amountRemaining" },
            releasedAmount: { $sum: "$amountReleased" },
            refundAmount: { $sum: "$amountRefunded" },
