            { key: "paid_commission", label: "Paid Commission", value: roundMoney(ledgerTotals.bySource.COMMISSION?.credit || 0), format: "currency" },
          ],
          rows: commissionRows.slice(0, 50).map((row) => ({
            id: String(row._id),
