function roundMoney(value) {
  return Math.round(Number(value || 0) * 100) / 100;
}

function deriveOrderPaymentStatus({
  order = {},
  refundStatus = "",
  refundAmount = 0,
  grossAmount = 0,
}) {
  const currentStatus = String(order.paymentStatus || "Pending");
  if (
    currentStatus !== "Paid" &&
    currentStatus !== "Partially Paid" &&
    currentStatus !== "Refunded" &&
    currentStatus !== "Partially Refunded"
  ) {
    return currentStatus;
  }

  if (refundStatus !== "PROCESSED" && refundStatus !== "REFUNDED") {
    return currentStatus === "Refunded" || currentStatus === "Partially Refunded" ? currentStatus : "Paid";
  }

  return Number(refundAmount || 0) >= Number(grossAmount || order.totalAmount || 0) ? "Refunded" : "Partially Refunded";
}

function buildIdempotencyKey(prefix, source = "") {
  return `${prefix}:${crypto.createHash("sha256").update(String(source || "")).digest("hex").slice(0, 24)}`;
}

function getOrderStage(order = {}) {
  const normalized = String(order.status || "").trim().toUpperCase().replace(/\s+/g, "_");
  if (normalized === "PENDING" || normalized === "PLACED") return "PLACED";
  if (normalized === "CONFIRMED") return "CONFIRMED";
  if (normalized === "PACKED") return "PACKED";
  if (normalized === "SHIPPED") return "SHIPPED";
  if (normalized === "OUT_FOR_DELIVERY") return "OUT_FOR_DELIVERY";
  if (normalized === "DELIVERED") return "DELIVERED";
  return "PLACED";
}

function getPaymentMethodKey(order = {}, payment = null) {
  if (String(order.paymentMethod || payment?.method || "").toUpperCase() === "COD") {
    return "COD";
  }
  return "RAZORPAY";
}

function getGatewayFee(order = {}, payment = null) {
  return roundMoney(
    payment?.gatewayFeeAmount ||
      order?.priceBreakdown?.gatewayFee ||
      order?.paymentRecordId?.gatewayFeeAmount ||
      0
  );
}

function isCodAdvanceOrder(order = {}) {
  return (
    String(order.paymentMethod || "").toUpperCase() === "COD" &&
    (
      Number(order.advanceAmount || 0) > 0 ||
      Number(order.codAdvance?.advanceAmount || 0) > 0 ||
      order.codAdvance?.enabled === true ||
      order.paymentMode === "COD_ADVANCE"
    )
  );
}

function isNormalCodWithoutAdvance(order = {}) {
  return String(order.paymentMethod || "").toUpperCase() === "COD" && !isCodAdvanceOrder(order);
}

function cancellationFeeBlocksRefund(refund = {}, order = {}) {
  const fee = Number(refund.cancellationFee || order.cancellation?.cancellationFee || 0);
  if (fee <= 0) return false;
  return !(refund.cancellationFeePaid || order.cancellation?.cancellationFeePaid);
}

function getRefundAdvancePaid(refund = {}, order = {}) {
  return Number(
    refund.breakdown?.advancePaid ??
      order.advanceAmount ??
      order.codAdvance?.advanceAmount ??
      0
  );
}

function getRefundCancellationFee(refund = {}, order = {}) {
  const explicitFee = Number(
    refund.cancellationFee ||
      order.cancellation?.cancellationFee ||
      order.cancellation?.preview?.cancellationFee ||
      0
  );
  if (explicitFee > 0) return explicitFee;
  if (
    String(refund.paymentMethod || order.paymentMethod || "").toUpperCase() === "COD" &&
    getRefundAdvancePaid(refund, order) <= 0 &&
    Number(refund.deductionAmount || 0) > 0
  ) {
    return Number(refund.deductionAmount || 0);
  }
  return 0;
}

function isCustomerPaidCancellationFeeRefund(refund = {}, order = {}) {
  const paymentMethod = String(refund.paymentMethod || order.paymentMethod || "").toUpperCase();
  return paymentMethod === "COD" && getRefundAdvancePaid(refund, order) <= 0 && getRefundCancellationFee(refund, order) > 0;
}

function getPolicyPaymentConfig(policy, paymentMethod) {
  return (policy.paymentMethodConfigs || []).find((item) => item.paymentMethod === paymentMethod) || null;
}

function ensureCancelableStage(order, stageRule) {
  if (order.status === "Cancelled" || order.cancellation?.status === "CANCELLED") {
    throw new AppError("Order is already cancelled", 409, "ORDER_ALREADY_CANCELLED");
  }
  if (!stageRule?.cancellationEnabled) {
    throw new AppError("Cancellation is disabled for this order stage", 409, "CANCELLATION_DISABLED");
  }
}

function ensureFeatureFlags(policy, paymentMethod) {
  const flags = policy.featureFlags || {};
  if (paymentMethod === "COD" && flags.codCancellationEnabled === false) {
    throw new AppError("COD cancellation is disabled", 409, "CANCELLATION_DISABLED");
  }
  if (paymentMethod === "RAZORPAY" && flags.razorpayCancellationEnabled === false) {
    throw new AppError("Razorpay cancellation is disabled", 409, "CANCELLATION_DISABLED");
  }
}

function ensureRefundFeatureFlags(policy, paymentMethod, refundMethod) {
  const flags = policy.featureFlags || {};
  if (paymentMethod === "COD" && flags.codRefundEnabled === false) {
    throw new AppError("COD refunds are disabled", 409, "REFUND_DISABLED");
  }
  if (paymentMethod === "RAZORPAY" && flags.razorpayRefundEnabled === false && refundMethod === "RAZORPAY") {
    throw new AppError("Razorpay refunds are disabled", 409, "REFUND_DISABLED");
  }
  if (refundMethod === "MANUAL" && flags.manualRefundEnabled === false) {
    throw new AppError("Manual refunds are disabled", 409, "REFUND_DISABLED");
  }
  if (refundMethod === "WALLET" && flags.walletRefundEnabled === false) {
    throw new AppError("Wallet refunds are disabled", 409, "REFUND_DISABLED");
  }
  if (refundMethod === "RAZORPAY" && flags.autoRefundEnabled === false) {
    throw new AppError("Auto refunds are disabled", 409, "REFUND_DISABLED");
  }
}

function calculateDeductionAmount(deduction = {}, context = {}) {
  if (deduction.enabled === false) return 0;
  const type = String(deduction.type || "").toUpperCase();
  let amount = 0;

  if (type === "FIXED") {
    amount = Number(deduction.value || 0);
  } else if (type === "PERCENTAGE") {
    amount = roundMoney(Number(context.refundableBase || 0) * (Number(deduction.value || 0) / 100));
  } else if (type === "SHIPPING") {
    amount = Number(deduction.value || context.shipping || 0);
  } else if (type === "GATEWAY_FEE") {
    amount = Number(context.gatewayFee || deduction.value || 0);
  } else if (type === "VENDOR_COMPENSATION") {
    amount = Number(deduction.value || 0);
  }

  const capAmount =
    deduction.capAmount === null || deduction.capAmount === undefined ? null : Number(deduction.capAmount || 0);
  if (capAmount !== null) {
    amount = Math.min(amount, capAmount);
  }
  return roundMoney(Math.max(0, amount));
}

function decideRefundMethod({ paymentMethod, payment, policy, paymentConfig }) {
  const allowed = new Set(paymentConfig?.allowedRefundMethods || []);
  if (paymentMethod === "RAZORPAY" && payment?.razorpayPaymentId && allowed.has("RAZORPAY")) {
    return "RAZORPAY";
  }
  if (allowed.has("WALLET") && policy.featureFlags?.walletRefundEnabled !== false) {
    return "WALLET";
  }
  return "MANUAL";
}

function normalizeRefundMethod(method = "") {
  const normalized = String(method || "").trim().toUpperCase();
  return ["RAZORPAY", "MANUAL", "WALLET"].includes(normalized) ? normalized : "";
}

function resolveFinanceSelectedRefundMethod(refund = {}, payload = {}) {
  return normalizeRefundMethod(payload.refundMethod || refund.refundMethod || refund.recommendedRefundMethod);
}

function buildRefundPreview({ order, payment, policy }) {
  const stage = getOrderStage(order);
  const paymentMethod = getPaymentMethodKey(order, payment);
  const stageRule = (policy.stages || []).find((item) => item.stage === stage);
  const paymentConfig = getPolicyPaymentConfig(policy, paymentMethod);

  if (!stageRule) throw new AppError("No cancellation rule configured for this order stage", 409, "POLICY_MISSING");
  ensureCancelableStage(order, stageRule);
  ensureFeatureFlags(policy, paymentMethod);

  const subtotal = roundMoney(order.subtotal || order.priceBreakdown?.subtotal || 0);
  const shipping = roundMoney(order.shippingFee || order.priceBreakdown?.shippingFee || 0);
  const taxes = roundMoney(order.taxAmount || order.priceBreakdown?.taxAmount || 0);
  const couponDiscount = roundMoney(order.discountAmount || order.priceBreakdown?.discountAmount || 0);
  const platformFee = roundMoney(order.platformFee || 0);
  const gatewayFee = getGatewayFee(order, payment);
  const grossOrderAmount = roundMoney(order.totalAmount || order.priceBreakdown?.totalAmount || 0);
  const isCodAdvance = paymentMethod === "COD" && isCodAdvanceOrder(order);
  const isNormalCod = paymentMethod === "COD" && !isCodAdvance;
  const normalCodHasDeductions =
    isNormalCod && (stageRule.deductions || []).some((deduction) => deduction?.enabled !== false);
  const grossAmount = isCodAdvance
    ? roundMoney(order.advanceAmount || order.codAdvance?.advanceAmount || payment?.amount || 0)
    : normalCodHasDeductions
      ? 0
    : grossOrderAmount;
  const refundableBase = isNormalCod ? grossOrderAmount : grossAmount;
  const deductions = (stageRule.deductions || []).map((deduction) => ({
    type: deduction.type,
    label: deduction.label,
    amount: calculateDeductionAmount(deduction, {
      refundableBase,
      subtotal,
      shipping,
      taxes,
      couponDiscount,
      platformFee,
      gatewayFee,
    }),
  }));
  const rawDeductionAmount = roundMoney(deductions.reduce((sum, item) => sum + Number(item.amount || 0), 0));
  const deductionAmount = roundMoney(Math.min(isNormalCod ? grossOrderAmount : grossAmount, rawDeductionAmount));
  const refundAmount = normalCodHasDeductions ? 0 : roundMoney(Math.max(0, grossAmount - deductionAmount));
  const cancellationFee = normalCodHasDeductions ? deductionAmount : 0;
  const refundMethod = decideRefundMethod({ paymentMethod, payment, policy, paymentConfig });
  const approvalRequired = Boolean(stageRule.manualApproval && !stageRule.autoApproval);

  return {
    stage,
    orderStatus: order.status,
    paymentMethod,
    approvalRequired,
    autoApproval: !approvalRequired,
    refundStatus: refundAmount > 0 ? (approvalRequired ? "PENDING" : "PROCESSING") : "NONE",
    refundMethod,
    grossAmount,
    deductionAmount,
    refundAmount,
    cancellationFee,
    cancellationFeePaymentRequired: cancellationFee > 0 && order.cancellation?.cancellationFeePaid !== true,
    cancellationFeePaid: Boolean(order.cancellation?.cancellationFeePaid),
    cancellationFeePaymentStatus: order.cancellation?.cancellationFeePaymentStatus || (cancellationFee > 0 ? "PENDING" : "NOT_REQUIRED"),
    breakdown: {
      subtotal,
      shipping,
      taxes,
      couponDiscount,
      platformFee,
      gatewayFee,
      cancellationDeduction: deductionAmount,
      orderTotal: grossOrderAmount,
      advancePaid: isCodAdvance ? grossAmount : 0,
      cancellationFee,
      deductions,
    },
    featureFlags: policy.featureFlags,
    paymentConfig,
    stageRule,
    policyId: policy._id,
    refundSlaHours: Number(stageRule.refundSlaHours || 0),
  };
}

class CancellationRefundService {
  getRazorpayClient() {
    const keyId = process.env.RAZORPAY_KEY_ID;
    const keySecret = process.env.RAZORPAY_KEY_SECRET;
    if (!keyId || !keySecret) {
      throw new AppError("Razorpay is not configured", 500, "RAZORPAY_NOT_CONFIGURED");
    }
    return new Razorpay({ key_id: keyId, key_secret: keySecret });
  }

  async loadOrderForActor(orderId, actor) {
    if (!mongoose.isValidObjectId(orderId)) {
      throw new AppError("Invalid orderId", 400, "VALIDATION_ERROR");
    }
    const order = await orderRepo.findById(orderId);
    if (!order) throw new AppError("Order not found", 404, "NOT_FOUND");

    if (actor?.role === "user" && String(order.userId?._id || order.userId) !== String(actor.sub || actor._id)) {
      throw new AppError("Forbidden", 403, "FORBIDDEN");
    }
    return order;
  }

  async getCancellationPreview(orderId, actor) {
    const order = await this.loadOrderForActor(orderId, actor);
    const payment = order.paymentRecordId?._id
      ? await paymentRepo.findById(order.paymentRecordId._id)
      : order.paymentRecordId
        ? await paymentRepo.findById(order.paymentRecordId)
        : null;
    const policy = await cancellationPolicyService.getActivePolicy();
    const preview = await buildRefundPreview({ order, payment, policy });
    return {
      orderId: order._id,
      orderNumber: order.orderNumber,
      status: order.status,
      cancellation: preview,
    };
  }

  async createCancellationFeeOrder({ order, preview, actor, reason = "", notes = "", meta = {} }) {
    if (!isNormalCodWithoutAdvance(order) || Number(preview.cancellationFee || 0) <= 0) {
      return null;
    }
    await paymentService.assertGatewayEnabled();
    const existingRazorpayOrderId = order.cancellation?.cancellationFeeRazorpayOrderId;
    if (existingRazorpayOrderId && order.cancellation?.cancellationFeePaymentStatus === "PENDING") {
      const existingPayment = await paymentRepo.findByRazorpayOrderId(existingRazorpayOrderId).catch(() => null);
      if (existingPayment && Number(existingPayment.amount || 0) === Number(preview.cancellationFee || 0) && existingPayment.status !== "FAILED") {
        return {
          paymentId: existingPayment._id,
          razorpayOrderId: existingRazorpayOrderId,
          razorpay_order_id: existingRazorpayOrderId,
          orderId: existingRazorpayOrderId,
          amount: Math.round(Number(preview.cancellationFee || 0) * 100),
          amountMajor: preview.cancellationFee,
          currency: existingPayment.currency || order.currency || "INR",
          key: process.env.RAZORPAY_KEY_ID,
          key_id: process.env.RAZORPAY_KEY_ID,
          receipt: existingPayment.receipt,
          title: "Cancellation Fee",
          description: `Cancellation charge for order ${order.orderNumber}`,
        };
      }
    }
    const razorpay = this.getRazorpayClient();
    const amount = Math.round(Number(preview.cancellationFee || 0) * 100);
    const currency = order.currency || "INR";
    const receipt = `cncl_${String(order._id).slice(-18)}_${Date.now().toString().slice(-6)}`;
    const gatewayOrder = await razorpay.orders.create({
      amount,
      currency,
      receipt,
      notes: {
        orderId: String(order._id),
        orderNumber: String(order.orderNumber || ""),
        purpose: "cancellation_fee",
        reason: String(reason || "").slice(0, 120),
      },
    });

    if (!gatewayOrder?.id || !String(gatewayOrder.id).startsWith("order_") || Number(gatewayOrder.amount) !== amount) {
      throw new AppError("Invalid Razorpay cancellation fee order. Please retry.", 502, "RAZORPAY_ORDER_VALIDATION_FAILED");
    }

    const paymentRecord = await paymentRepo.create({
      userId: order.userId?._id || order.userId,
      orderIds: [order._id],
      amount: preview.cancellationFee,
      currency,
      method: "ONLINE",
      paymentMode: "CANCELLATION_FEE",
      status: "CREATED",
      fulfillmentStatus: "PENDING",
      receipt,
      razorpayOrderId: gatewayOrder.id,
      amountBreakdown: {
        totalAmount: preview.cancellationFee,
        paymentMethod: "ONLINE",
      },
      gatewayResponse: {
        purpose: "cancellation_fee",
        gatewayOrder,
        cancellationPreview: preview,
        reason,
        notes,
      },
    });

    await Order.updateOne(
      { _id: order._id },
      {
        $set: {
          "cancellation.reason": String(reason || "").trim(),
          "cancellation.requestedAt": new Date(),
          "cancellation.requestedByRole": actor?.role || "user",
          "cancellation.requestedById": actor?.sub || actor?._id || null,
          "cancellation.currentStageKey": preview.stage,
          "cancellation.policyId": preview.policyId,
          "cancellation.preview": preview,
          "cancellation.cancellationFee": preview.cancellationFee,
          "cancellation.cancellationFeePaid": false,
          "cancellation.cancellationFeePaymentId": String(paymentRecord._id),
          "cancellation.cancellationFeeRazorpayOrderId": gatewayOrder.id,
          "cancellation.cancellationFeePaymentStatus": "PENDING",
          "cancellation.cancellationFeeGateway": "RAZORPAY",
        },
        $push: {
          timeline: {
            status: "Cancellation Fee Pending",
            note: `Cancellation fee ${preview.cancellationFee} must be paid before cancellation`,
            timestamp: new Date(),
          },
        },
      }
    );

    await auditService.log({
      actor,
      action: "order.cancellation_fee.payment_initiated",
      entityType: "Order",
      entityId: order._id,
      metadata: {
        amount: preview.cancellationFee,
        razorpayOrderId: gatewayOrder.id,
        paymentRecordId: paymentRecord._id,
        ipAddress: meta?.ipAddress,
      },
      ipAddress: meta?.ipAddress,
      userAgent: meta?.userAgent,
    }).catch(() => null);

    return {
      paymentId: paymentRecord._id,
      razorpayOrderId: gatewayOrder.id,
      razorpay_order_id: gatewayOrder.id,
      orderId: gatewayOrder.id,
      amount: gatewayOrder.amount,
      amountMajor: preview.cancellationFee,
      currency,
      key: process.env.RAZORPAY_KEY_ID,
      key_id: process.env.RAZORPAY_KEY_ID,
      receipt,
      title: "Cancellation Fee",
      description: `Cancellation charge for order ${order.orderNumber}`,
    };
  }

  async verifyCancellationFeePayment({ orderId, actor, razorpay_order_id, razorpay_payment_id, razorpay_signature, reason = "", notes = "", meta = {} }) {
    const order = await this.loadOrderForActor(orderId, actor);
    const payment = await paymentRepo.findByRazorpayOrderId(razorpay_order_id);
    if (!payment || String(payment.paymentMode) !== "CANCELLATION_FEE" || String(payment.orderIds?.[0]?._id || payment.orderIds?.[0]) !== String(order._id)) {
      throw new AppError("Cancellation fee payment reference is invalid", 400, "INVALID_CANCELLATION_FEE_PAYMENT");
    }
    if (String(payment.userId?._id || payment.userId) !== String(actor?.sub || actor?._id)) {
      throw new AppError("Forbidden", 403, "FORBIDDEN");
    }

    const expectedSignature = crypto
      .createHmac("sha256", process.env.RAZORPAY_KEY_SECRET || "")
      .update(`${razorpay_order_id}|${razorpay_payment_id}`)
      .digest("hex");
    const actual = Buffer.from(String(razorpay_signature || ""), "hex");
    const expected = Buffer.from(expectedSignature, "hex");
    if (actual.length !== expected.length || !crypto.timingSafeEqual(actual, expected)) {
      await paymentRepo.updateById(payment._id, { $set: { status: "FAILED", failedAt: new Date() } }).catch(() => null);
      await Order.updateOne(
        { _id: order._id },
        { $set: { "cancellation.cancellationFeePaymentStatus": "FAILED" } }
      ).catch(() => null);
      throw new AppError("Cancellation fee payment verification failed", 400, "PAYMENT_SIGNATURE_INVALID");
    }

    const gatewayPayment = await paymentService.fetchGatewayPayment(razorpay_payment_id);
    if (String(gatewayPayment?.order_id || "") !== String(razorpay_order_id) || String(gatewayPayment?.status || "").toLowerCase() !== "captured") {
      throw new AppError("Cancellation fee payment is not captured by Razorpay", 409, "PAYMENT_NOT_CAPTURED");
    }

    await paymentRepo.updateById(payment._id, {
      $set: {
        status: "PAID",
        fulfillmentStatus: "COMPLETED",
        razorpayPaymentId: razorpay_payment_id,
        razorpaySignature: razorpay_signature,
        paidAt: new Date(),
        gatewayResponse: {
          ...(payment.gatewayResponse || {}),
          verifiedPayment: gatewayPayment,
        },
      },
    });

    await Order.updateOne(
      { _id: order._id },
      {
        $set: {
          "cancellation.cancellationFeePaid": true,
          "cancellation.cancellationFeePaymentId": String(payment._id),
          "cancellation.cancellationFeeRazorpayOrderId": razorpay_order_id,
          "cancellation.cancellationFeeTransactionId": razorpay_payment_id,
          "cancellation.cancellationFeePaymentStatus": "PAID",
          "cancellation.cancellationFeeGateway": "RAZORPAY",
          "cancellation.cancellationFeePaidAt": new Date(),
        },
        $push: {
          timeline: {
            status: "Cancellation Fee Paid",
            note: `Cancellation fee paid through Razorpay (${razorpay_payment_id})`,
            timestamp: new Date(),
          },
        },
      }
    );

    await auditService.log({
      actor,
      action: "order.cancellation_fee.payment_success",
      entityType: "Order",
      entityId: order._id,
      metadata: {
        amount: payment.amount,
        razorpayOrderId: razorpay_order_id,
        razorpayPaymentId: razorpay_payment_id,
      },
      ipAddress: meta?.ipAddress,
      userAgent: meta?.userAgent,
    }).catch(() => null);

    return this.processOrderCancellation({
      orderId,
      actor,
      meta,
      reason: reason || order.cancellation?.reason,
      notes,
      skipCancellationFeeGate: true,
    });
  }

  async createCustomerWalletRefund(userId, amount, referenceId, note, { session = null } = {}) {
    const user = await User.findById(userId).session(session || null);
    if (!user) throw new AppError("User not found", 404, "NOT_FOUND");
    user.wallet = user.wallet || {};
    user.wallet.balance = roundMoney(Number(user.wallet.balance || 0) + Number(amount || 0));
    user.wallet.totalCredited = roundMoney(Number(user.wallet.totalCredited || 0) + Number(amount || 0));
    user.wallet.lastUpdatedAt = new Date();
    const transactions = Array.isArray(user.wallet.transactions) ? user.wallet.transactions : [];
    transactions.push({
      type: "CREDIT",
      amount: roundMoney(amount),
      source: "ORDER_CANCELLATION_REFUND",
      referenceId: String(referenceId || ""),
      note: String(note || ""),
      createdAt: new Date(),
    });
    user.wallet.transactions = transactions.slice(-100);
    await user.save({ session: session || undefined });
    return user.wallet;
  }

  async restoreInventoryForOrder(order, actorId, { session = null } = {}) {
    if (order.cancellation?.inventoryRestored || order.inventoryRestoredAt) {
      return { skipped: true, reason: "INVENTORY_ALREADY_RESTORED" };
    }

    const sellerId = order.sellerId?._id || order.sellerId;
    const skippedItems = [];
    const skippableInventoryErrors = new Set(["INVALID_UNRESERVE", "VARIANT_NOT_FOUND", "PRODUCT_NOT_FOUND"]);
    for (const item of order.items || []) {
      if (!order.inventoryCommittedAt) {
        try {
          await inventoryService.unreserveStock(
            item.productId?._id || item.productId,
            item.variantId || "",
            Number(item.quantity || 0),
            order._id,
            sellerId,
            actorId,
            { session }
          );
        } catch (error) {
          // Some legacy orders were created without an inventory reservation.
          // In that case there is nothing to release, so cancellation should continue.
          if (skippableInventoryErrors.has(error?.code)) {
            skippedItems.push({
              productId: item.productId?._id || item.productId,
              variantId: item.variantId || "",
              quantity: Number(item.quantity || 0),
              code: error.code,
              reason: error.message,
            });
            continue;
          }
          throw error;
        }
      } else {
        try {
          await inventoryService.restoreStock(
            item.productId?._id || item.productId,
            item.variantId || "",
            Number(item.quantity || 0),
            null,
            order._id,
            sellerId,
            actorId,
            "Order cancelled by policy engine",
            { session }
          );
        } catch (error) {
          if (skippableInventoryErrors.has(error?.code)) {
            skippedItems.push({
              productId: item.productId?._id || item.productId,
              variantId: item.variantId || "",
              quantity: Number(item.quantity || 0),
              code: error.code,
              reason: error.message,
            });
            continue;
          }
          throw error;
        }
      }
    }

    return { restored: true, skippedItems };
  }

  async rollbackSettlementArtifacts(order, refundRef, { session = null } = {}) {
    const payouts = await payoutRepo.findByOrderId(order._id);
    const cancellablePayouts = payouts.filter((payout) => ["ON_HOLD", "PENDING", "QUEUED"].includes(payout.status));
    for (const payout of cancellablePayouts) {
      await payoutRepo.updateById(payout._id, {
        $set: {
          status: "CANCELLED",
          notes: `Cancelled by cancellation/refund engine (${refundRef || "no-ref"})`,
        },
      });
    }

    if (order.vendorWalletReleasedAt) {
      await paymentService.applyRefundWalletReversal(
        order,
        Number(order.refundSummary?.amount || order.totalAmount || 0),
        refundRef,
        { session }
      );
      return { reversed: true, mode: "LEDGER_ADJUSTMENT" };
    }

    return { reversed: false, mode: "PENDING_SETTLEMENT_CANCELLED" };
  }

  async createRefundRecord({
    order,
    payment,
    preview,
    actor,
    reason,
    notes,
    refundMethod,
    approvalStatus = "AUTO_APPROVED",
    session = null,
  }) {
    const idempotencyKey = buildIdempotencyKey(
      "refund",
      `${order._id}:${preview.refundAmount}:${preview.deductionAmount}:${refundMethod}:${reason || ""}`
    );

    const existing = await Refund.findOne({ idempotencyKey }).session(session || null);
    if (existing) {
      return existing;
    }
    const isCustomerPaidCancellationFee = Number(preview.refundAmount || 0) <= 0 && Number(preview.cancellationFee || 0) > 0;

    const refund = await Refund.create(
      [
        {
          orderId: order._id,
          paymentId: payment?._id || order.paymentRecordId || null,
          idempotencyKey,
          amount: preview.refundAmount,
          deductionAmount: preview.deductionAmount,
          grossAmount: preview.grossAmount,
          status: isCustomerPaidCancellationFee ? "PROCESSED" : "PENDING",
          reason: reason || "Order cancelled",
          gateway: "",
          refundMethod: "",
          recommendedRefundMethod: isCustomerPaidCancellationFee ? "" : refundMethod,
          refundType: "CANCELLATION",
          requestedByRole: actor?.role || "system",
          requestedById: actor?.sub || actor?._id || null,
          paymentMethod: order.paymentMethod,
          cancellationFee: Number(order.cancellation?.cancellationFee || preview.cancellationFee || 0),
          cancellationFeePaid: Boolean(order.cancellation?.cancellationFeePaid),
          cancellationFeePaymentStatus: order.cancellation?.cancellationFeePaymentStatus || (preview.cancellationFee > 0 ? "PENDING" : "NOT_REQUIRED"),
          cancellationFeePaymentId: order.cancellation?.cancellationFeePaymentId || "",
          cancellationFeeGateway: order.cancellation?.cancellationFeeGateway || "",
          cancellationFeePaidAt: order.cancellation?.cancellationFeePaidAt || null,
          attemptCount: 0,
          lastAttemptAt: new Date(),
          retryable: !isCustomerPaidCancellationFee,
          approval: {
            status: isCustomerPaidCancellationFee ? "AUTO_APPROVED" : approvalStatus,
            ...(isCustomerPaidCancellationFee || approvalStatus === "APPROVED" || approvalStatus === "AUTO_APPROVED"
              ? { approvedBy: actor?.sub || actor?._id || null, approvedAt: new Date() }
              : {}),
          },
          breakdown: {
            ...preview.breakdown,
            refundAmount: preview.refundAmount,
          },
          notes: notes || "",
          ...(isCustomerPaidCancellationFee ? { processedAt: new Date() } : {}),
        },
      ],
      { session: session || undefined }
    );

    return refund[0];
  }

  async triggerRefund(refund, order, payment, actor, { session = null } = {}) {
    const refundMethod = refund.refundMethod;
    const policy = await cancellationPolicyService.getActivePolicy();
    ensureRefundFeatureFlags(policy, getPaymentMethodKey(order, payment), refundMethod);
    let nextStatus = "PROCESSED";
    let failureReason = "";

    try {
      if (refundMethod === "RAZORPAY") {
        if (!payment?.razorpayPaymentId) {
          throw new AppError("Razorpay payment reference missing", 409, "PAYMENT_REFERENCE_MISSING");
        }
        const razorpay = this.getRazorpayClient();

      } else {
//         gatewayResponse = {
          id: `manual_refund_${Date.now()}`,
          status: "pending_manual_action",
        };
        nextStatus = "PENDING";
      }
    } catch (error) {
      nextStatus = "FAILED";
      failureReason = error.message;
//       gatewayResponse = {
        error: error.message,
        code: error.code || error.statusCode || "REFUND_FAILED",
      };
    }

    const update = {
      $set: {
        status: nextStatus,
//         gatewayResponse,
        failureReason,
        lastAttemptAt: new Date(),
      },
      $inc: {
        attemptCount: 1,
      },
      $push: {
        retryHistory: {
          attemptedAt: new Date(),
          status: nextStatus,
          note: failureReason || `Refund dispatched via ${refundMethod}`,
        },
      },
    };

    if (nextStatus === "PROCESSED") {
      update.$set.processedAt = new Date();
    }
    if (nextStatus === "FAILED") {
      update.$set.failedAt = new Date();
    }
//     if (nextStatus === "PENDING" && gatewayResponse?.id) {
//       update.$set.refundId = gatewayResponse.id;
    }

    const updatedRefund = await Refund.findByIdAndUpdate(refund._id, update, {
      returnDocument: "after",
      session: session || undefined,
    });

    const nextRefundedAmount = roundMoney(Number(payment?.refundedAmount || 0) + Number(updatedRefund.amount || 0));
    const isFullRefund = nextRefundedAmount >= Number(payment?.amount || order.totalAmount || 0);
    if (payment?._id) {
      await paymentRepo.updateById(payment._id, {
        $set: {
          refundedAmount: nextRefundedAmount,
          refundStatus:
            nextStatus === "FAILED" ? payment.refundStatus || "NONE" : nextStatus === "PENDING" ? "PENDING" : isFullRefund ? "FULL" : "PARTIAL",
          status:
            nextStatus === "FAILED"
              ? payment.status
              : nextStatus === "PENDING"
                ? "REFUND_PENDING"
                : isFullRefund
                  ? "REFUNDED"
                  : "PARTIALLY_REFUNDED",
        },
      });
    }

    return updatedRefund;
  }

  async processOrderCancellation({
    orderId,
    actor,
    meta,
    reason,
    notes,
    previewOnly = false,
    skipCancellationFeeGate = false,
  }) {
    const order = await this.loadOrderForActor(orderId, actor);
    const payment = order.paymentRecordId?._id
      ? await paymentRepo.findById(order.paymentRecordId._id)
      : order.paymentRecordId
        ? await paymentRepo.findById(order.paymentRecordId)
        : null;
    const policy = await cancellationPolicyService.getActivePolicy();
    const preview = await buildRefundPreview({ order, payment, policy });

    if (previewOnly) {
      return {
        previewOnly: true,
        orderId: order._id,
        orderNumber: order.orderNumber,
        preview,
      };
    }

    if (
      !skipCancellationFeeGate &&
      isNormalCodWithoutAdvance(order) &&
      Number(preview.cancellationFee || 0) > 0 &&
      order.cancellation?.cancellationFeePaid !== true
    ) {
      const cancellationFeePayment = await this.createCancellationFeeOrder({ order, preview, actor, reason, notes, meta });
      return {
        requiresCancellationFeePayment: true,
        orderId: order._id,
        orderNumber: order.orderNumber,
        preview,
        cancellationFeePayment,
        message: "Cancellation fee payment is required before cancelling this order.",
      };
    }

    const claim = await Order.findOneAndUpdate(
      {
        _id: order._id,
        "cancellation.status": { $nin: ["REQUESTED", "APPROVED", "CANCELLED"] },
        status: { $ne: "Cancelled" },
      },
      {
        $set: {
          "cancellation.status": preview.approvalRequired ? "REQUESTED" : "APPROVED",
          "cancellation.reason": String(reason || "").trim(),
          "cancellation.requestedAt": new Date(),
          "cancellation.requestedByRole": actor?.role || "system",
          "cancellation.requestedById": actor?.sub || actor?._id || null,
          "cancellation.currentStageKey": preview.stage,
          "cancellation.policyId": preview.policyId,
          "cancellation.autoApproved": !preview.approvalRequired,
          "cancellation.preview": preview,
          "cancellation.idempotencyKey": buildIdempotencyKey("cancel", `${order._id}:${reason || ""}:${preview.refundAmount}`),
          "refundSummary.status": preview.refundAmount > 0 ? "PENDING" : "NONE",
          "refundSummary.method": preview.refundMethod,
          "refundSummary.amount": preview.refundAmount,
          "refundSummary.deductionAmount": preview.deductionAmount,
          "refundSummary.grossAmount": preview.grossAmount,
          "refundSummary.pendingSince": preview.refundAmount > 0 ? new Date() : null,
        },
      },
      { returnDocument: "after" }
    ).exec();

    if (!claim) {
      const latest = await orderRepo.findById(order._id);
      if (latest?.cancellation?.status === "CANCELLED" || latest?.status === "Cancelled") {
        return {
          duplicate: true,
          order: latest,
        };
      }
      throw new AppError("Cancellation is already being processed", 409, "CANCELLATION_IN_PROGRESS");
    }

    const refundMethod = preview.refundMethod;
    const approvalStatus = preview.approvalRequired ? "PENDING_REVIEW" : "AUTO_APPROVED";

    const result = await withOptionalTransaction(
      async (session) => {
        await this.restoreInventoryForOrder(claim, actor?.sub || actor?._id, { session });

        const shouldCreateRefundVisibilityRow =
          preview.refundAmount > 0 ||
          (isNormalCodWithoutAdvance(claim) && Number(preview.cancellationFee || 0) > 0 && claim.cancellation?.cancellationFeePaid === true);
        const refund =
          shouldCreateRefundVisibilityRow
            ? await this.createRefundRecord({
                order: claim,
                payment,
                preview,
                actor,
                reason,
                notes,
                refundMethod,
                approvalStatus,
                session,
              })
            : null;

        await Order.updateOne(
          { _id: claim._id },
          {
            $set: {
              status: "Cancelled",
              paymentStatus: claim.paymentStatus,
              cancelledAt: new Date(),
              cancelReason: String(reason || "").trim(),
              settlementStatus:
                claim.paymentMethod === "COD" ? "CANCELLED" : claim.settlementStatus === "SETTLED" ? "REVERSED" : "CANCELLED",
              inventoryReservationReleasedAt: claim.inventoryCommittedAt ? claim.inventoryReservationReleasedAt : new Date(),
              inventoryRestoredAt: new Date(),
              "cancellation.status": "CANCELLED",
              "cancellation.approvedAt": new Date(),
              "cancellation.approvedByRole": actor?.role || "system",
              "cancellation.approvedById": actor?.sub || actor?._id || null,
              "cancellation.cancellationProcessedAt": new Date(),
              "cancellation.inventoryRestored": true,
              "cancellation.inventoryRestoredAt": new Date(),
              "cancellation.shipmentCancellationAttemptedAt": new Date(),
              "refundSummary.status": preview.refundAmount > 0 ? "PENDING" : "NONE",
              "refundSummary.method": "",
              "refundSummary.processedAt": null,
              "refundSummary.lastAttemptAt": null,
              "refundSummary.failedAt": null,
              "refundSummary.failureReason": "",
              ...(refund ? { refundId: refund._id } : {}),
            },
            $push: {
              timeline: {
                status: "Cancelled",
                note: preview.refundAmount > 0 ? `Cancelled with refund ${preview.refundAmount}` : "Cancelled with no refund",
                timestamp: new Date(),
              },
            },
          },
          { session: session || undefined }
        );

        await this.rollbackSettlementArtifacts(
          { ...claim.toObject(), refundSummary: { amount: preview.refundAmount } },
          refund?.refundId || refund?._id || "",
          { session }
        );

        const freshOrder = await orderRepo.findById(claim._id);
        return { order: freshOrder, refund };
      },
      { source: "cancellation-refund.service.cancel" }
    );

    await auditService.log({
      actor,
      action: "order.cancellation.processed",
      entityType: "Order",
      entityId: orderId,
      metadata: {
        reason,
        refundAmount: preview.refundAmount,
        deductionAmount: preview.deductionAmount,
        refundMethod,
        paymentMethod: order.paymentMethod,
        ipAddress: meta?.ipAddress,
        deviceInfo: meta?.userAgent,
      },
      ipAddress: meta?.ipAddress,
      userAgent: meta?.userAgent,
    });

    await Promise.all([
      productAnalyticsService.refreshForOrder(orderId),
      notificationService.notifyVendorAndOperations({
        vendorId: order.sellerId?._id || order.sellerId,
        permissionKey: "orders.read",
        module: "MANAGEMENT",
        subModule: "RETURNS",
        type: "ORDER_CANCELLED",
        title: "Order cancelled",
        message: `Order ${order.orderNumber} was cancelled${preview.refundAmount > 0 ? ` with refund ${preview.refundAmount}` : ""}.`,
        referenceId: order._id,
        meta: {
          orderNumber: order.orderNumber,
          refundAmount: preview.refundAmount,
          deductionAmount: preview.deductionAmount,
        },
      }),
    ]);

    return {
      order: result.order,
      refund: result.refund,
      preview,
    };
  }

  async listRefunds(query = {}) {
    await cancellationPolicyService.ensureDefaultPolicy();
    const filters = {};
    if (query.status) filters.status = query.status;
    if (query.startDate) filters.startDate = query.startDate;
    if (query.endDate) filters.endDate = query.endDate;
    const refunds = await refundRepo.list({
      ...filters,
      limit: Math.min(Math.max(Number(query.limit || 100), 1), 200),
    });

    const grouped = refunds.map((refund) => {
      const row = refund.toObject?.() || refund;
      const order = row.orderId || refund.orderId || null;
      const customerPaidFee = isCustomerPaidCancellationFeeRefund(row, order || {});
      const cancellationFee = getRefundCancellationFee(row, order || {});
      return {
        ...row,
        amount: customerPaidFee ? 0 : row.amount,
        grossAmount: customerPaidFee ? 0 : row.grossAmount,
        status: customerPaidFee ? "PROCESSED" : row.status,
        refundMethod: customerPaidFee ? "" : row.refundMethod,
        recommendedRefundMethod: customerPaidFee ? "" : row.recommendedRefundMethod,
        retryable: customerPaidFee ? false : row.retryable,
        cancellationFee,
        cancellationFeePaid: customerPaidFee ? true : row.cancellationFeePaid,
        cancellationFeePaymentStatus: customerPaidFee ? "PAID" : row.cancellationFeePaymentStatus,
        customerPaidCancellationFee: customerPaidFee,
        orderStatus: order?.status || "",
        paymentMethod: order?.paymentMethod || row.paymentMethod || "",
        customer: order?.userId || null,
        unifiedPricingBreakdown: order ? pricingBreakdownEngine.buildFromOrder(order) : null,
      };
    });

    if (!query.status || query.status === "PROCESSED") {
      const refundOrderIds = new Set(
        grouped
          .map((refund) => String(refund.orderId?._id || refund.orderId || ""))
          .filter(Boolean)
      );
      const orderQuery = {
        paymentMethod: "COD",
        $or: [
          { "cancellation.cancellationFeePaid": true },
          { "cancellation.cancellationFeePaymentStatus": "PAID" },
        ],
      };
      if (query.startDate || query.endDate) {
        orderQuery.$and = [
          {
            $or: [
              { "cancellation.cancellationFeePaidAt": {} },
              { updatedAt: {} },
            ],
          },
        ];
        if (query.startDate) {
          orderQuery.$and[0].$or[0]["cancellation.cancellationFeePaidAt"].$gte = new Date(query.startDate);
          orderQuery.$and[0].$or[1].updatedAt.$gte = new Date(query.startDate);
        }
        if (query.endDate) {
          orderQuery.$and[0].$or[0]["cancellation.cancellationFeePaidAt"].$lte = new Date(query.endDate);
          orderQuery.$and[0].$or[1].updatedAt.$lte = new Date(query.endDate);
        }
      }

      const feeOnlyOrders = await Order.find(orderQuery)
        .populate("userId", "name email phone")
        .populate("sellerId", "companyName shopName supportPhone")
        .populate("paymentRecordId", "status method amount razorpayOrderId razorpayPaymentId refundedAmount refundStatus")
        .sort({ updatedAt: -1 })
        .limit(Math.min(Math.max(Number(query.limit || 100), 1), 200))
        .exec();

      for (const order of feeOnlyOrders) {
        if (refundOrderIds.has(String(order._id))) continue;
        if (isCodAdvanceOrder(order)) continue;
        const cancellationFee = getRefundCancellationFee({}, order);
        if (cancellationFee <= 0) continue;
        const row = {
          _id: `cancellation-fee:${order._id}`,
          orderId: order,
          paymentId: order.paymentRecordId || null,
          refundId: "",
          idempotencyKey: `cancellation-fee:${order._id}`,
          amount: 0,
          deductionAmount: cancellationFee,
          grossAmount: 0,
          status: "PROCESSED",
          reason: order.cancellation?.reason || "COD cancellation fee paid",
          gateway: "",
          refundMethod: "",
          recommendedRefundMethod: "",
          refundType: "CANCELLATION",
          requestedByRole: order.cancellation?.requestedByRole || "user",
          requestedById: order.userId?._id || order.userId || null,
          paymentMethod: "COD",
          cancellationFee,
          cancellationFeePaid: true,
          cancellationFeePaymentStatus: "PAID",
          cancellationFeePaymentId: order.cancellation?.cancellationFeePaymentId || "",
          cancellationFeeGateway: order.cancellation?.cancellationFeeGateway || "RAZORPAY",
          cancellationFeePaidAt: order.cancellation?.cancellationFeePaidAt || order.updatedAt,
          retryable: false,
          approval: {
            status: "AUTO_APPROVED",
            approvedAt: order.cancellation?.cancellationFeePaidAt || order.updatedAt,
          },
          breakdown: {
            refundAmount: 0,
            cancellationDeduction: cancellationFee,
          },
          notes: "Customer paid COD cancellation fee. No refund is due.",
          processedAt: order.cancellation?.cancellationFeePaidAt || order.updatedAt,
          createdAt: order.cancellation?.cancellationFeePaidAt || order.updatedAt,
          updatedAt: order.updatedAt,
          customerPaidCancellationFee: true,
          orderStatus: order.status || "",
          customer: order.userId || null,
          unifiedPricingBreakdown: pricingBreakdownEngine.buildFromOrder(order),
        };
        grouped.push(row);
      }

      grouped.sort((a, b) => new Date(b.createdAt || 0) - new Date(a.createdAt || 0));
      grouped.splice(Math.min(Math.max(Number(query.limit || 100), 1), 200));
    }

    const overview = grouped.reduce(
      (acc, refund) => {
        const amount = Number(refund.amount || 0);
        acc.totalAmount += amount;
        if (refund.status === "PROCESSED") acc.processedAmount += amount;
        if (refund.status === "PENDING" || refund.status === "PROCESSING") acc.pendingAmount += amount;
        if (refund.status === "FAILED") acc.failedAmount += amount;
        if (refund.status === "REJECTED") acc.rejectedAmount += amount;
        return acc;
      },
      { totalAmount: 0, processedAmount: 0, pendingAmount: 0, failedAmount: 0, rejectedAmount: 0 }
    );

    return { refunds: grouped, overview };
  }

  async getRefundDetails(refundId) {
    const refund = await refundRepo.findById(refundId);
    if (!refund) throw new AppError("Refund not found", 404, "NOT_FOUND");
    const order = await orderRepo.findById(refund.orderId?._id || refund.orderId);
    const payment = await paymentRepo.findById(refund.paymentId?._id || refund.paymentId);
    return {
      refund,
      order: order ? pricingBreakdownEngine.attachToOrder(order) : order,
      payment,
      inventoryLogs: order?._id
        ? await require("../models/InventoryLedger").InventoryLedger.find({ orderId: order._id }).sort({ createdAt: -1 }).lean()
        : [],
      auditLogs: await require("../models/AuditLog").AuditLog.find({
        $or: [{ entityId: String(refund._id) }, { entityId: String(order?._id || "") }],
      })
        .sort({ createdAt: -1 })
        .lean(),
    };
  }

  async processRefundAction(refundId, actor, payload = {}, meta = {}) {
    const refund = await refundRepo.findById(refundId);
    if (!refund) throw new AppError("Refund not found", 404, "NOT_FOUND");
    const order = await orderRepo.findById(refund.orderId?._id || refund.orderId);
    const payment = await paymentRepo.findById(refund.paymentId?._id || refund.paymentId);
    if (!order) throw new AppError("Linked order not found", 404, "NOT_FOUND");

    if (payload.action === "approve") {
      if (cancellationFeeBlocksRefund(refund, order)) {
        throw new AppError("Cancellation fee must be paid before refund processing", 409, "CANCELLATION_FEE_PENDING");
      }
      if (refund.status === "PROCESSED") {
        return { refund, order, payment, duplicate: true };
      }
      const refundMethod = resolveFinanceSelectedRefundMethod(refund, payload);
      if (!refundMethod) {
        throw new AppError("Refund method must be selected by finance", 400, "VALIDATION_ERROR");
      }

      await Refund.updateOne(
        { _id: refund._id },
        {
          $set: {
            "approval.status": "APPROVED",
            "approval.approvedBy": actor?.sub || actor?._id || null,
            "approval.approvedAt": new Date(),
            refundMethod,
            gateway: refundMethod,
            status: "PROCESSING",
          },
        }
      );

      const updatedRefund = await this.triggerRefund(
        { ...refund.toObject?.() || refund, refundMethod, gateway: refundMethod, amount: refund.amount },
        order,
        payment,
        actor
      );

      await Order.updateOne(
        { _id: order._id },
        {
          $set: {
            paymentStatus: deriveOrderPaymentStatus({
              order,
              refundStatus: updatedRefund.status,
              refundAmount: updatedRefund.amount,
              grossAmount: updatedRefund.grossAmount || order.totalAmount,
            }),
            "refundSummary.status":
              updatedRefund.status === "PROCESSED"
                ? "REFUNDED"
                : updatedRefund.status === "FAILED"
                  ? "FAILED"
                  : "PROCESSING",
            "refundSummary.method": updatedRefund.refundMethod || refundMethod,
            "refundSummary.processedAt": updatedRefund.processedAt || null,
            "refundSummary.failedAt": updatedRefund.failedAt || null,
            "refundSummary.failureReason": updatedRefund.failureReason || "",
            "refundSummary.retryCount": Number(updatedRefund.attemptCount || 0),
            "refundSummary.lastAttemptAt": updatedRefund.lastAttemptAt || new Date(),
          },
        }
      );

      await auditService.log({
        actor,
        action: "refund.approved",
        entityType: "Refund",
        entityId: refundId,
        metadata: { orderId: String(order._id), refundMethod },
        ipAddress: meta?.ipAddress,
        userAgent: meta?.userAgent,
      });

      return {
        refund: await refundRepo.findById(refundId),
        order: await orderRepo.findById(order._id),
        payment: payment?._id ? await paymentRepo.findById(payment._id) : null,
      };
    }

    if (payload.action === "reject") {
      const updated = await Refund.findByIdAndUpdate(
        refund._id,
        {
          $set: {
            status: "REJECTED",
            failedAt: new Date(),
            "approval.status": "REJECTED",
            "approval.approvedBy": actor?.sub || actor?._id || null,
            "approval.approvedAt": new Date(),
            "approval.rejectionReason": String(payload.notes || payload.reason || "Rejected by admin"),
          },
        },
        { returnDocument: "after" }
      );
      await Order.updateOne(
        { _id: order._id },
        {
          $set: {
            "refundSummary.status": "FAILED",
            "refundSummary.failedAt": new Date(),
            "refundSummary.failureReason": updated.approval?.rejectionReason || "Rejected by admin",
          },
        }
      );
      return { refund: updated, order: await orderRepo.findById(order._id), payment };
    }

    throw new AppError("Unsupported refund action", 400, "VALIDATION_ERROR");
  }

