  async listPayments(query = {}) {
    const result = await paymentRepo.list({
      page: Number(query.page || 1),
      limit: Number(query.limit || 20),
      status: query.status,
      method: query.method,
      search: query.search,
      startDate: query.startDate,
      endDate: query.endDate,
    });
    const payments = result.payments.map(decoratePayment);

    const overview = payments.reduce(
      (acc, payment) => {
        const amount = Number(payment.amount || 0);
        acc.totalAmount += amount;
        acc.totalCount += 1;
        acc.gatewayFeeRevenue += Number(payment.gatewayFeeAmount || payment.amountBreakdown?.gatewayFee || 0);
        if (payment.status === "PAID") acc.paidAmount += amount;
        if (payment.status === "FAILED") acc.failedAmount += amount;
        if (payment.status === "REFUNDED" || payment.status === "PARTIALLY_REFUNDED") {
          acc.refundedAmount += Number(payment.refundedAmount || 0);
        }
        return acc;
      },
      {
        totalAmount: 0,
        paidAmount: 0,
        failedAmount: 0,
        refundedAmount: 0,
        gatewayFeeRevenue: 0,
        totalCount: 0,
      }
    );

    overview.successRate = overview.totalCount ? roundMoney((overview.paidAmount > 0 ? payments.filter((p) => p.status === "PAID").length / overview.totalCount : 0) * 100) : 0;
    overview.refundRate = overview.totalCount
      ? roundMoney(
          (payments.filter((p) => ["REFUNDED", "PARTIALLY_REFUNDED"].includes(p.status)).length / overview.totalCount) * 100
        )
      : 0;

    return { ...result, payments, overview };
  }

