      await orderRepo.updateById(order._id, {
        ...(order.invoiceNumber ? {} : { invoiceNumber: snapshot.invoiceNumber }),
        ...(order.orderSnapshot ? {} : { orderSnapshot: snapshot }),
      });
      order.invoiceNumber = order.invoiceNumber || snapshot.invoiceNumber;
